/**
 * Long-form detail for every denial code in the dataset.
 *
 * The dataset in `denial-codes.ts` ships as one searchable tool page and that
 * remains the entry point. This file adds genuine depth — a worked example,
 * cross-references and an FAQ block — so each code also gets its own route at
 * /denial-codes/[code].
 *
 * This covers all 190 as of 2026-09-01, reversing an earlier decision to write
 * only the 54 with obvious demand. That decision was made from competitor
 * revealed preference and a "not enough data" keyword reading; Search Console
 * position data then showed denial pages ranking at a median of 21 and a best
 * of 4.8 while every other page type on the site sat between 58 and 88. Being
 * able to win the query mattered more than the volume behind it.
 *
 * The anti-thin-content rule survives the reversal and is the real constraint:
 * `generateStaticParams` reads this file rather than `denialCodes`, so a page
 * cannot exist until someone has written substance for it. Bar is ~450 words
 * of code-specific prose, and 8-word shingle overlap against sibling pages
 * under ~35%.
 */

export type DenialCodeDetail = {
  code: string;
  /**
   * Compact plain-English label for the page title.
   *
   * The official `title` in denial-codes.ts runs to 95 characters, so it
   * cannot drive a title, and without this the title was "CO-97 Denial Code
   * | Vizora" at 26 characters — matching the bare code query and nothing
   * else. Keep under 40 characters so the rendered title lands near 55.
   */
  shortLabel: string;
  /** A concrete scenario showing the denial arising and being resolved. */
  example: string[];
  /** Additional depth beyond the meaning/fix/prevent triple. */
  context: string[];
  /** Other codes commonly seen alongside or confused with this one. */
  relatedCodes: string[];
  /** Glossary slugs. */
  relatedTerms: string[];
  /** Service slugs. */
  relatedServices: string[];
  faqs: { question: string; answer: string }[];
};

